import json,glob,yaml
d=json.load(open('/tmp/rm.json'))
items={i['id']:i for i in d['items']}
tasks=[yaml.safe_load(open(f)) for f in glob.glob('.archon-horizon/tasks/items/*.yaml')]
live={t['id'] for t in tasks if t.get('status')=='running'}
own={}
for t in tasks:
    for r in (t.get('roadmap_refs') or []): own.setdefault(r,[]).append((t['id'],t.get('status')))
def anc(i):
    out=[]
    p=items.get(i,{}).get('parent') or ''
    while p:
        out.append(p); p=items.get(p,{}).get('parent') or ''
    return out
act=[i['id'] for i in d['items'] if i['status']=='active']
# rows directly held by a live task
direct={a for a in act if any(t in live for t,_ in own.get(a,[]))}
# any row (any status) held by live task -> its active ancestors are legitimate
livespine=set()
for r,os_ in own.items():
    if any(t in live for t,_ in os_):
        for a in anc(r):
            if a in act: livespine.add(a)
print("live tasks:",sorted(live))
print("\nDIRECT (%d):"%len(direct)); [print("  ",x) for x in sorted(direct)]
print("\nANCESTOR-of-live (%d):"%len(livespine-direct)); [print("  ",x,"<-",own.get(x)) for x in sorted(livespine-direct)]
orph=[a for a in act if a not in direct and a not in livespine]
print("\nORPHAN candidates (%d):"%len(orph))
for a in orph: print("  ",a,"owners:",own.get(a),"| children:",[(c['id'],c['status']) for c in d['items'] if c.get('parent')==a])
print("\ntotal active",len(act))
